function fmtDuration(s){
  s=Math.round(Number(s)||0);
  if(s<60) return s+' 秒';
  var m=Math.floor(s/60), r=s%60;
  if(m<60) return m+' 分 '+r+' 秒';
  var h=Math.floor(m/60); m=m%60;
  if(h<24) return h+' 小时 '+m+' 分';
  var d=Math.floor(h/24); h=h%24;
  return d+' 天 '+h+' 小时';
}
function downloadTime(sizeBytes, mbps){
  if(mbps==null) mbps=10;
  mbps=Number(mbps); if(!(mbps>0)) return {ok:false, reason:'bandwidth must be > 0'};
  var bits=(Number(sizeBytes)||0)*8;
  var secs=bits/(mbps*1e6);
  return {ok:true, seconds:secs, human:fmtDuration(secs)};
}

var EXPORTS={fmtDuration:fmtDuration,downloadTime:downloadTime};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DownloadTimeForgePure = EXPORTS; }
